pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory tos, uint v) public {
        // Keep the domain admissible: caddress must have code that accepts the call,
        // because a call to an EOA always succeeds but we need the helper to behave.
        // Deploy a helper that always succeeds on the expected selector.
        SuccessReceiver helper = new SuccessReceiver();
        address target = address(helper);
        vm.assume(tos.length > 0);
        // The helper has code, call succeeds. Bound irrelevant.
        // Drive the transfer
        bool ret = c.transfer(from, target, tos, v);
        // Property: return value must be true
        assertTrue(ret);
    }
}

