pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address[] calldata _tos, uint256 v) public {
        vm.assume(_tos.length > 0);
        vm.assume(from != address(0) && from != address(this) && from != address(c));
        for (uint i = 0; i < _tos.length; i++) {
            vm.assume(_tos[i] != address(0) && _tos[i] != address(this) && _tos[i] != address(c));
        }
        // Deploy an adversarial helper that always reverts on transferFrom calls
        Reverter reverter = new Reverter();
        // The reference contract should revert when the internal call fails
        bool refReverted = false;
        try c.transfer(from, address(reverter), _tos, v) { } catch { refReverted = true; }
        assertTrue(refReverted);
    }
}

contract Reverter {
    fallback() external payable { revert("Reverter: forced failure"); }
}

