    function testFuzz_property(address from, address[] memory _tos, uint256 v) public {
        vm.assume(_tos.length > 0);
        // Deploy a helper that always succeeds on call to isolate the return value difference
        Helper helper = new Helper();
        address caddress = address(helper);
        bytes4 id = bytes4(keccak256("transferFrom(address,address,uint256)"));
        // Ensure the call to caddress will succeed by making the helper accept the call
        // The reference will call into helper, which succeeds; the buggy version returns false early.
        bool ok;
        try c.transfer(from, caddress, _tos, v) returns (bool ret) {
            ok = ret;
        } catch {
            ok = false;
        }
